#include "stdlib/complex/float64/base/assert/is_not_equal.h"
#include "stdlib/complex/float64/reim.h"
#include "stdlib/complex/float64/ctor.h"
#include <stdbool.h>

/**
* Tests whether two double-precision complex floating-point numbers are not equal.
*
* @param z1    first double-precision complex floating-point number
* @param z2    second double-precision complex floating-point number
* @return      boolean indicating if both complex numbers are not equal
*
* @example
* #include "stdlib/complex/float64/ctor.h"
* #include <stdbool.h>
*
* stdlib_complex128_t z1 = stdlib_complex128( 5.0, 2.0 );
* stdlib_complex128_t z2 = stdlib_complex128( 5.0, -2.0 );
*
* bool v = stdlib_base_complex128_is_not_equal( z1, z2 );
*/
bool stdlib_base_complex128_is_not_equal( const stdlib_complex128_t z1, const stdlib_complex128_t z2 ) {
	double re1;
	double re2;
	double im1;
	double im2;
	stdlib_complex128_reim( z1, &re1, &im1 );
	stdlib_complex128_reim( z2, &re2, &im2 );
	return ( re1 != re2 || im1 != im2 );
}","lineStart":1,"lineEnd":48,"totalLines":48,"truncated":false}},"title":"repos/pc-lib-3456/complex-float64-base-assert-is-not-equal/src/main.c","time":{"start":1783264017124,"end":1783264017128}},"id":"prt_f32d17967001lagK8vN6kTQDRm","sessionID":"ses_0cd2ec215ffemWrRUfcMa1VS2D","messageID":"msg_f32d1720e0010a8M8oC4zARBDo"}}

