'use strict';

// MODULES //

var bench = require( '@stdlib/bench-harness' );
var Complex128 = require( '@stdlib/complex-float64-ctor' );
var randu = require( '@stdlib/random-base-randu' );
var isBoolean = require( '@stdlib/assert-is-boolean' ).isPrimitive;
var pkg = require( './../package.json' ).name;
var isNotEqual = require( './../lib' );


// MAIN //

bench( pkg, function benchmark( b ) {
	var z1;
	var z2;
	var v;
	var i;

	z1 = [
		new Complex128( randu(), randu() ),
		new Complex128( randu(), randu() )
	];
	z2 = [
		new Complex128( randu(), randu() ),
		new Complex128( randu(), randu() ),
		z1[ 0 ],
		z1[ 1 ]
	];

	b.tic();
	for ( i = 0; i < b.iterations; i++ ) {
		v = isNotEqual( z1[ i%z1.length ], z2[ i%z2.length ] );
		if ( typeof v !== 'boolean' ) {
			b.fail( 'should return a boolean' );
		}
	}
	b.toc();
	if ( !isBoolean( v ) ) {
		b.fail( 'should return a boolean' );
	}
	b.pass( 'benchmark finished' );
	b.end();
});","lineStart":1,"lineEnd":63,"totalLines":63,"truncated":false}},"title":"repos/pc-lib-3456/complex-float64-base-assert-is-not-equal/benchmark/benchmark.js","time":{"start":1783264036745,"end":1783264036797}},"id":"prt_f32d1c60d001FPV4ANCnqDvXwZ","sessionID":"ses_0cd2ec215ffemWrRUfcMa1VS2D","messageID":"msg_f32d1b12f001K1453gUmnJZ5cs"}}

